import math
phase='fwd'
dist=0.0
looks=[(-23,'camera'),(-65,'right_mirror'),(43,'left_mirror'),(-100,'right'),(100,'left')]
li=0
lt=None
seen={}

def pts(v):
    o=v.get('origin') or [0,0]
    out=[]
    for w in v.get('walls') or []:
        b=math.radians(w[0]);d=w[1]
        out.append((round(o[0]+d*math.cos(b),1),round(o[1]+d*math.sin(b),1)))
    return out

def control(obs):
    global phase,dist,li,lt
    t=obs['t'];dt=obs.get('dt',0.1)
    h=obs['hitch_deg']
    v=obs['motion']['v_mps']
    dist+=abs(v)*dt
    if phase=='fwd':
        if dist>2.8 and abs(h)<3:
            phase='stop'
        else:
            return (0.0,1.0,-23)
    if phase=='stop':
        if abs(v)<0.02:
            phase='look';lt=t
        return (0.0,0.0,-23)
    if phase=='look':
        g,name=looks[li]
        if obs['head'].get('settled') and t-lt>0.6:
            for k,vw in (obs.get('views') or {}).items():
                if vw: print(name,k,pts(vw))
            li+=1;lt=t
            if li>=len(looks):
                phase='done'
                print('rig',obs['rig']['trailer_rear'],'h',h,'prog',obs['progress'])
                print('target',obs.get('target'))
                wake('survey done')
                return (0.0,0.0,-23)
            g=looks[li][0]
        return (0.0,0.0,g)
    return (0.0,0.0,-23)

