import math
X=0.0;Y=0.0;TH=0.0
pts={}
tgt=None
mode='rev'
lastp=-10
woke=False

def wrap(a):
    while a>180: a-=360
    while a<-180: a+=360
    return a

def clamp(x,a,b):
    return max(a,min(b,x))

def w2v(wx,wy):
    c=math.cos(TH);s=math.sin(TH)
    dx=wx-X;dy=wy-Y
    return dx*c+dy*s, -dx*s+dy*c

def v2w(px,py):
    c=math.cos(TH);s=math.sin(TH)
    return X+px*c-py*s, Y+px*s+py*c

def control(obs):
    global X,Y,TH,tgt,mode,lastp,woke
    t=obs['t'];dt=obs.get('dt',0.1) or 0.1
    mo=obs['motion'];v=mo['v_mps'];st=obs['steer_deg']
    TH+=v/2.5*math.tan(math.radians(st))*dt
    X+=v*math.cos(TH)*dt;Y+=v*math.sin(TH)*dt
    views=obs.get('views') or {}
    for name,vw in views.items():
        if not vw: continue
        ox,oy=vw['origin']
        for w in vw.get('walls',[]) or []:
            b,d=w[0],w[1]
            px=ox+d*math.cos(math.radians(b));py=oy+d*math.sin(math.radians(b))
            wx,wy=v2w(px,py)
            pts[(round(wx/0.3),round(wy/0.3))]=(wx,wy,t)
    if len(pts)>2500 or int(t*10)%50==0:
        for k in [k for k,p in pts.items() if t-p[2]>25]:
            del pts[k]
    tg=obs.get('target') or {}
    if tg.get('in_sight') and tg.get('dist_m') is not None:
        b=math.radians(tg['bearing_deg']);d=tg['dist_m']
        tgt=v2w(0.75+d*math.cos(b),d*math.sin(b))+(t,)
    rig=obs['rig'];hitch=obs['hitch_deg']
    Rx,Ry=rig['trailer_rear']
    rear=rig['trailer_heading_deg']+180.0
    look=150 if (t%7.0)<3.5 else -150
    status=obs.get('status')
    if status=='JACKKNIFED' or abs(hitch)>45:
        mode='fwd'
    if mode=='fwd':
        if abs(hitch)<8:
            mode='rev'
        else:
            return (clamp(-1.0*hitch,-35,35),1.0,look)
    loc=[]
    for p in pts.values():
        px,py=w2v(p[0],p[1])
        if (px-Rx)**2+(py-Ry)**2<400: loc.append((px-Rx,py-Ry))
    def free(th):
        ux=math.cos(math.radians(th));uy=math.sin(math.radians(th))
        m=15.0
        for dx,dy in loc:
            a=dx*ux+dy*uy
            if a<=0.3 or a>=m: continue
            if abs(ux*dy-uy*dx)<1.5: m=a
        return m
    ths=[rear+k*3 for k in range(-20,21)]
    fs=[free(th) for th in ths]
    best=None;bs=-1e9
    for i in range(len(ths)):
        sm=sum(fs[max(0,i-2):i+3])/len(fs[max(0,i-2):i+3])
        sc=min(sm,12)-0.03*abs(ths[i]-rear)
        if sc>bs: bs=sc;best=ths[i]
    err=wrap(best-rear)
    ux=math.cos(math.radians(rear));uy=math.sin(math.radians(rear))
    dl=4.0;dr=4.0
    for dx,dy in loc:
        a=dx*ux+dy*uy
        if a<-4.6 or a>1.5: continue
        l=ux*dy-uy*dx
        if l>0: dl=min(dl,l)
        else: dr=min(dr,-l)
    err+=clamp(6.0*(dl-dr),-12,12)
    if tgt is not None and t-tgt[2]<20:
        tx,ty=w2v(tgt[0],tgt[1])
        dd=math.hypot(tx-Rx,ty-Ry)
        if dd<12:
            et=wrap(math.degrees(math.atan2(ty-Ry,tx-Rx))-rear)
            wgt=clamp((12-dd)/6.0,0,1)
            err=(1-wgt)*err+wgt*et
    hd=clamp(1.0*err,-30,30)
    steer=clamp(2.5*(hitch-hd),-45,45)
    f0=free(rear)
    sp=-1.0
    if abs(hitch-hd)>15 or f0<3: sp=-0.6
    if f0<0.5:
        if not woke:
            wake('rail close behind trailer, stopping'); woke=True
        sp=0.0
    if t-lastp>5:
        lastp=t
        print('t%.0f h%.0f hd%.0f err%.0f st%.0f f0%.1f dl%.1f dr%.1f n%d tgt%s'%(t,hitch,hd,err,steer,f0,dl,dr,len(loc),tgt is not None))
    return (steer,sp,look)

