touches=None
nw=0
LOOK=[(150,2.0),(64,0.8),(0,0.8),(-64,0.8),(-150,2.0),(-64,0.8),(0,0.8),(64,0.8)]

def clamp(x,a,b):
    return max(a,min(b,x))

def w2v(wx,wy):
    c=math.cos(TH);s=math.sin(TH)
