def boxd(px,py,cx,cy,c,s,x0,x1,hw):
    dx=px-cx;dy=py-cy
    lx=dx*c+dy*s;ly=-dx*s+dy*c
    ex=max(x0-lx,0.0,lx-x1);ey=max(abs(ly)-hw,0.0)
    return math.hypot(ex,ey),lx,ly

def control(obs):
    try:
        return _control(obs)
    except Exception as e:
        print('ERR',e)
