        elif -4.6<=a<1.0:
            if lat>0: L0=lat if L0 is None else min(L0,lat)
            else: R0=-lat if R0 is None else min(R0,-lat)
    def cen(L,R):
        if L is not None and R is not None: return (L-R)/2.0
        if L is not None: return L-2.1
        if R is not None: return 2.1-R
        return 0.0
    c1=cen(L1,R1);c0=cen(L0,R0)
