    hd=clamp(hd,-35,35)
    steer=clamp(2.5*(hitch-hd),-45,45)
    sp=-0.45
    if mc<0.6 or abs(hitch-hd)>12: sp=-0.3
    if int(t*10)%30==0:
        print('  c1%.1f c0%.1f ang%.0f hd%.0f steer%.0f' %(c1,c0,ang,hd,steer))
    return (steer,sp,look_at(t))

