        ff=math.degrees(math.atan(L*math.sin(pr)/(B+A*math.cos(pr))))
        steer=clamp(ff+3.0*(phi-phi_ref),-45,45)
        rem=(obs.get('progress') or {}).get('remaining',10) or 10
        spd=-0.6 if rem>2.5 else -0.4
        if st['n']%20==0:
            print('t=%.1f phi=%.1f ref=%.1f th=%.1f gam=%.1f e=%.2f w=%s nL=%d nR=%d st=%.1f'%(obs.get('t',0),phi,phi_ref,thc,math.degrees(gam),e,st['w'] and round(st['w'],2),len(left),len(right),steer))
        return (steer,spd,170)
    except Exception as ex:
        if st['n']%20==0: print('err',ex)
        steer=clamp(3.0*phi,-45,45)
        return (steer,-0.4,170)

