import math
phase='rev'
phid=0.0
tick=0
last_th=0.0

def control(obs):
    global phase, phid, tick, last_th
    tick+=1
    rig=obs['rig']; phi=obs['hitch_deg']
    look=rig.get('screen_gaze_deg')
    if look is None: look=-41
    if phase=='fwd':
        if abs(phi)<8:
            phase='rev'
        return (0.0,1.5,look)
    if abs(phi)>48 or obs.get('status')=='JACKKNIFED':
        phase='fwd'
        return (0.0,1.5,look)
    R=rig['trailer_rear']; ht=math.radians(rig['trailer_heading_deg']); hw=rig['trailer_half_width']
    ch=math.cos(ht); sh=math.sin(ht)
    def tf(x,y):
        dx=x-R[0]; dy=y-R[1]
        return (-(dx*ch+dy*sh), -dx*sh+dy*ch)
    views=obs.get('views') or {}
    pts=[]; corners=[]
    for name,v in views.items():
        if not v: continue
        ox,oy=v['origin']
        for p in v.get('walls',[]) or []:
            b,d=p[0],p[1]
            x=ox+d*math.cos(math.radians(b)); y=oy+d*math.sin(math.radians(b))
            pts.append(tf(x,y))
        if name=='camera':
            for p in v.get('target_corners',[]) or []:
                try:
                    b,d=p[0],p[1]
                    x=ox+d*math.cos(math.radians(b)); y=oy+d*math.sin(math.radians(b))
                    corners.append(tf(x,y))
                except Exception:
                    pass
    th=None
    if pts:
        def free(t):
            r=math.radians(t); c=math.cos(r); s=math.sin(r)
            f=15.0
            for u,w in pts:
                if u<-0.5: continue
                a=u*c+w*s; q=-u*s+w*c
                if a>0 and abs(q)<hw+0.35:
                    f=min(f,a)
            return f
        cands=[(t,free(t)) for t in range(-70,71,5)]
        mf=max(f for t,f in cands)
        wl=None; wr=None
        for u,w in pts:
            if 0<u<6:
                if w>0: wl=w if wl is None else min(wl,w)
                elif w<0: wr=-w if wr is None else min(wr,-w)
        thc=0.0
        if wl is not None and wr is not None:
            thc=math.degrees(math.atan2((wl-wr)/2.0,5.0))
        good=[t for t,f in cands if f>=mf-0.7]
        th=min(good,key=lambda t:abs(t-thc))
        if mf>=8 and abs(th-thc)<=5: th=thc
        if corners:
            cu=sum(c[0] for c in corners)/len(corners); cw=sum(c[1] for c in corners)/len(corners)
            if cu>1.0:
                tt=math.degrees(math.atan2(cw,cu))
                if free(tt)>=min(cu,15)-1.0:
                    th=tt
        last_th=th
    else:
        th=last_th*0.95
        last_th=th
    new=max(-35.0,min(35.0,1.0*th))
    phid=0.7*phid+0.3*new
    steer=1.6*phi-1.22*phid
    steer=max(-42.0,min(42.0,steer))
    sp=-1.0
    if abs(phi-phid)>20: sp=-0.6
    if tick%20==0:
        print('t=%.1f phi=%.1f phid=%.1f th=%.1f steer=%.1f npts=%d corners=%d'%(obs['t'],phi,phid,th,steer,len(pts),len(corners)))
    return (steer,sp,look)

